output_text:
[
  {
    "id": "pedestrian_aisles_no_carts",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelf_canyon": {
          "and": [
            "single_file",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelf_canyon"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_pedestrian_aisle_with_cart",
    "text": "An agent may not move into a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelf_canyon": {
          "and": [
            "single_file",
            "adjShelf"
          ]
        }
      },
      "events": {
        "cart_enters_shelf_canyon": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "shelf_canyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_enters_shelf_canyon"
    }
  },
  {
    "id": "park_cart_at_pedestrian_aisle_mouth",
    "text": "Before using the narrow pedestrian shopping aisles, the cart must be set down at an aisle mouth.",
    "abstraction": {
      "state_properties": {
        "aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "pedestrian_shelf_aisle": {
          "and": [
            "single_file",
            "adjShelf"
          ]
        }
      },
      "events": {
        "arrive_at_aisle_mouth_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "aisle_mouth",
              "hasCart"
            ]
          }
        },
        "cart_parked": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "aisle_mouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_aisle_mouth_with_cart",
      "discharge": "cart_parked"
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_aisle",
    "text": "After returning from a narrow pedestrian shelf aisle, the agent must retrieve the parked cart before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "pedestrian_shelf_aisle": {
          "and": [
            "single_file",
            "adjShelf"
          ]
        }
      },
      "events": {
        "return_from_pedestrian_aisle_without_cart": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              },
              "pedestrian_shelf_aisle"
            ]
          },
          "post": {
            "and": [
              "aisle_mouth",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_from_pedestrian_aisle_without_cart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "open_shelf_service_requires_cart",
    "text": "Shelf interactions in open cart-accessible aisles must be performed while the agent has a cart.",
    "abstraction": {
      "state_properties": {
        "open_cart_aisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "open_shelf_service_position": {
          "and": [
            "open_cart_aisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "open_shelf_service_position",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "hand_pick_only_in_narrow_shelf_aisle",
    "text": "Interactions inside single-file shelf aisles are hand-picking actions and may not be done while holding a cart.",
    "abstraction": {
      "state_properties": {
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "hand_pick_zone": {
          "and": [
            "single_file",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hand_pick_zone",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cart_may_be_parked_only_at_staging_cells",
    "text": "A cart may be put down only at designated wide staging cells outside pedestrian shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cart_staging_cell": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "put_down_cart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "put_down_cart",
          {
            "not": "cart_staging_cell"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_leave_staging_cartless_to_open_store",
    "text": "After parking a cart at an aisle mouth, the agent may leave that cell without the cart only by entering the pedestrian shelf aisle.",
    "abstraction": {
      "state_properties": {
        "cart_staging_cell": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "single_file": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "pedestrian_shelf_aisle": {
          "and": [
            "single_file",
            "adjShelf"
          ]
        }
      },
      "events": {
        "cartless_leave_staging_to_open_store": {
          "pre": {
            "and": [
              "MOVE",
              "cart_staging_cell",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": {
            "not": "pedestrian_shelf_aisle"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_leave_staging_to_open_store"
    }
  }
]
